import{_ as t,o,c as s,ag as r}from"./chunks/framework.BZohXCq9.js";const p=JSON.parse('{"title":"Student Dashboard -> Progress Tracking (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/student-dashboard/progress-tracking.md","filePath":"modules/student-dashboard/progress-tracking.md"}'),d={name:"modules/student-dashboard/progress-tracking.md"};function a(l,e,n,i,c,u){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="student-dashboard-progress-tracking-deep" tabindex="-1">Student Dashboard -&gt; Progress Tracking (deep) <a class="header-anchor" href="#student-dashboard-progress-tracking-deep" aria-label="Permalink to &quot;Student Dashboard -&gt; Progress Tracking (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>student-dashboard</code><br><strong>Feature:</strong> <code>progress-tracking</code><br><strong>Routes:</strong> <code>/student-dashboard/reviews</code>, <code>/student-dashboard/allBookingSlots</code></p><p>This feature is the student learning-progress dashboard. It combines completed-hours metrics, remaining-hours metrics, days-since-last-lesson style indicators, and a slot table that links students into feedback/rating actions.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Show learning progress and lesson-hour state.</li><li>Show booking slots in a review-ready format.</li><li>Help students understand which completed lessons are still awaiting feedback/rating actions.</li><li>Provide drill-down routes to review all booking slots and feedback forms.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/components/StudentComponents/ReviewTab/Dashboard.tsx</code></td><td>Main progress page</td><td>Loads hours progress + booking-slot data and renders cards/charts/table.</td></tr><tr><td><code>Frontend/src/components/StudentComponents/ReviewTab/StudentHourPercentage.tsx</code></td><td>Progress stat card</td><td>Visualises completed/remaining hour states.</td></tr><tr><td><code>Frontend/src/components/StudentComponents/ReviewTab/BookingSlotTable.tsx</code></td><td>Slot table</td><td>Lists lesson slots, status, feedback state, and action buttons.</td></tr><tr><td><code>Frontend/src/components/StudentComponents/ReviewTab/AllBookingSlotPage.tsx</code></td><td>Expanded slot listing</td><td>Provides full list view of booking slots.</td></tr><tr><td><code>Frontend/src/components/StudentComponents/ReviewTab/ProgressChart.tsx</code></td><td>Chart helper</td><td>Present in codebase but partially dormant/commented in live page composition.</td></tr><tr><td><code>Frontend/src/hooks/ReviewSystem.ts</code></td><td>Review-system state hook</td><td>Coordinates booking-slot and review routing behavior.</td></tr><tr><td><code>Frontend/src/hooks/UseReview.ts</code></td><td>Review data helper</td><td>Shared review-fetch/update helpers.</td></tr><tr><td><code>Frontend/src/hooks/UseStudentHourProgress.ts</code></td><td>Hours-progress hook</td><td>Wraps hours progress query and formatting.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="get-student-hours-progress" tabindex="-1"><code>GET_STUDENT_HOURS_PROGRESS</code> <a class="header-anchor" href="#get-student-hours-progress" aria-label="Permalink to &quot;`GET_STUDENT_HOURS_PROGRESS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/ReviewQueries.ts</code></li><li>Query field: <code>getStudentHoursProgress(studentId: ID!)</code></li><li>Returns: <ul><li><code>totalRequiredHours</code></li><li><code>completedHours</code></li><li><code>remainingHours</code></li><li><code>studentInfo</code></li><li><code>bookingsBreakdown</code></li></ul></li><li>Used by: top progress cards.</li></ul><h3 id="get-all-student-booking-slots" tabindex="-1"><code>GET_ALL_STUDENT_BOOKING_SLOTS</code> <a class="header-anchor" href="#get-all-student-booking-slots" aria-label="Permalink to &quot;`GET_ALL_STUDENT_BOOKING_SLOTS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/ReviewQueries.ts</code></li><li>Query field: <code>getAllStudentBookingSlots</code></li><li>Used by: booking-slot table and “View all” page.</li></ul><h3 id="related-read-helpers" tabindex="-1">Related read helpers <a class="header-anchor" href="#related-read-helpers" aria-label="Permalink to &quot;Related read helpers&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/StudentDashboard.ts</code></li><li><code>GET_STUDENT_DASHBOARD_STATS</code> overlaps conceptually with this module but is primarily owned by the overview page.</li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs/student.typeDefs.js</code><ul><li>relevant progress/hour fields</li></ul></li><li>File: <code>server/src/graphql/typeDefs/ReviewTypes.js</code><ul><li>booking-slot and review-related shapes used by this feature</li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers/student.resolver.js</code><ul><li><code>Query.getStudentProgress</code></li><li><code>Query.getStudentLessonHours</code></li><li><code>Query.getStudentHoursProgress</code></li></ul></li><li>File: <code>server/src/graphql/resolvers/Review.resolver.js</code><ul><li><code>Query.getAllStudentBookingSlots</code></li></ul></li><li>File: <code>server/src/graphql/resolvers/studentDashboard.resolver.js</code><ul><li>dashboard stats overlap used in some progress summaries</li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/User.js</code></td><td>Stores student hour-related fields such as <code>lessonHoursLeft</code></td></tr><tr><td><code>server/src/models/studentBooking.model.js</code></td><td>Source for completed vs pending slots/bookings</td></tr><tr><td><code>server/src/models/Reviews.js</code></td><td>Helps determine reviewed vs unreviewed lesson state</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Student opens <code>/student-dashboard/reviews</code>.</li><li>The page loads student hour progress and booking-slot review data.</li><li>Cards show completed and remaining hours plus supporting status values.</li><li>Slot table shows lesson entries and whether they are reviewable.</li><li>Student can refresh the dataset or move into all-slot/review routes for specific lessons.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>This module is named “reviews” in the route but behaves as a progress dashboard, not just a ratings page.</li><li>Progress calculations are partly booking-derived and partly based on student profile hour fields (<code>lessonHoursLeft</code>), so debugging “remaining hours” often requires checking both bookings and profile state.</li><li>Some chart code exists but is not fully surfaced in the current page layout.</li></ul>',25)])])}const g=t(d,[["render",a]]);export{p as __pageData,g as default};
